import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第四十一卦 损 山泽损 艮上兑下","description":"周易 - 第四十一卦 损 山泽损 艮上兑下","frontmatter":{"title":"第四十一卦 损 山泽损 艮上兑下","description":"周易 - 第四十一卦 损 山泽损 艮上兑下"},"headers":[],"relativePath":"zh/classics/zhouyi/042.md","filePath":"zh/classics/zhouyi/042.md"}'),l={name:"zh/classics/zhouyi/042.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="损" tabindex="-1">损 <a class="header-anchor" href="#损" aria-label="Permalink to “损”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>有孚，元吉，无咎，可贞，利有攸往？曷之用，二簋可用享。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>损，损下益上，其道上行。损而有孚，元吉，无咎，可贞，利有攸往。曷之用？二簋可用享；二簋应有时。损刚益柔有时，损益盈虚，与时偕行。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>山下有泽，损；君子以惩忿窒欲。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>已事遄往，无咎，酌损之。象曰：已事 遄往，尚合志也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>利贞，征凶，弗损益之。象曰：九二利贞，中以为志也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>三人行，则损一人；一人行，则得其友。象曰：一人行，三则疑也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>损其疾，使遄有喜，无咎。象曰：损其疾，亦可喜也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>或益之，十朋之龟弗克违，元吉。象曰：六五元吉，自上佑也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>弗损益之，无咎，贞吉，利有攸往，得臣无家。象曰：弗损益之，大得志也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
